      ))}
    </div>
  );
}

/* ──────────────────────────────────────────────────────────
   EVENT FEED WIDGET
────────────────────────────────────────────────────────── */
function EventWidget({ event, robot }) {
  const statusMeta = {
    award:     { label: '🏆 Award',    cls: 'award'     },
    completed: { label: 'Completed',   cls: 'completed'  },
    upcoming:  { label: 'Upcoming',    cls: 'upcoming'   },
    debut:     { label: 'Debut',       cls: 'debut'      },
    competed:  { label: 'Competed',    cls: 'competed'   },
  };
  const meta = statusMeta[event.badge] ?? statusMeta[event.status] ?? { label: 'Event', cls: 'competed' };

  return (
    <div
      id={event.id}
      className={`event-widget ${event.highlight ? 'event-widget--award' : ''}`}
    >
      {/* Left accent bar (yellow on award) */}
      <div className="event-widget__accent" aria-hidden="true" />

      <div className="event-widget__body">
        {/* Top row: title + status + date */}
        <div className="event-widget__top">
          <div className="event-widget__title-group">
            <h3 className="event-widget__name">{event.name}</h3>
            <span className="event-widget__venue">📍 {event.venue}</span>
          </div>
          <div className="event-widget__right">
            <span className={`event-widget__status event-widget__status--${meta.cls}`}>
              {meta.label}
            </span>
            <span className="event-widget__date">{event.date}</span>
          </div>
        </div>

        {/* Detail paragraph */}
        <p className="event-widget__detail">
          {event.badge === 'debut' || event.badge === 'competed' || event.badge === 'award' ? (
            /* Inject robot name as yellow span on first mention */
            (() => {
              const text = event.detail;
              const idx  = text.indexOf(robot);
              if (idx === -1 || !robot || robot === 'TBD') return text;
              return (
                <>
                  {text.slice(0, idx)}
                  <span className="text-yellow font-semibold">{robot}</span>
                  {text.slice(idx + robot.length)}
                </>
              );
            })()
          ) : event.detail}
        </p>

        {/* Result chip */}
        {event.result && event.status !== 'upcoming' && (
          <div className="event-widget__result-row">
            <span className={`event-widget__result ${event.highlight ? 'event-widget__result--award' : ''}`}>
              {event.result}
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

